requests.testScript:
test('status is 200', () => {
  expect(response.status).toBe(200);
});
test('active workspace id is present', () => {
  expect(response.json().activeWorkspaceId).toBeDefined();
});
test('returns at least one workspace', () => {
  expect(response.json().workspaces.length).toBeGreaterThan(0);
});
test('remember the active workspace', () => {
  environment.set('activeWorkspaceIdBefore', response.json().activeWorkspaceId);
});

test('status is 200', () => {
  expect(response.status).toBe(200);
});
test('active workspace matches the listing', () => {
  expect(response.json().id).toBe(environment.get('activeWorkspaceIdBefore'));
});
test('workspace has a name and path', () => {
  expect(response.json().name).toBeDefined();
  expect(response.json().path).toBeDefined();
});

test('status is 200', () => {
  expect(response.status).toBe(200);
});
test('workspace gets a generated id', () => {
  expect(response.json().id).toMatch(/^ws-/);
});
test('workspace path points into the data dir', () => {
  expect(response.json().path).toContain(response.json().id);
  expect(response.json().path).toContain('workspaces');
});
test('capture id and path for later requests', () => {
  environment.set('createdWorkspaceId', response.json().id);
  environment.set('workspacePath', response.json().path);
  environment.set('workspacePathEncoded', encodeURIComponent(response.json().path));
});

test('status is 200', () => {
  expect(response.status).toBe(200);
});
test('activated workspace is the created one', () => {
  expect(response.json().id).toBe(environment.get('createdWorkspaceId'));
});

test('status is 200', () => {
  expect(response.status).toBe(200);
});
test('export carries the workspace name', () => {
  expect(response.json().name).toBe('Test Workspace');
});
test('export includes collection and environment bundles', () => {
  expect(Array.isArray(response.json()['collections.json'])).toBeTruthy();
  expect(response.json()['environments.json'].environments).toBeDefined();
});

test('status is 200', () => {
  expect(response.status).toBe(200);
});
test('created workspace path exists on disk', () => {
  expect(response.json().exists).toBe(true);
  expect(response.json().isDirectory).toBe(true);
});
